package com.thunder.agi.license

import android.content.Context
import android.util.Base64
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey
import org.json.JSONObject
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

/**
 * LicenseValidator for Thunder AGI.
 * Validates HMAC-SHA256-signed license keys generated by the Generator App.
 * Credentials stored in EncryptedSharedPreferences (AES-256).
 */
object LicenseValidator {

    // Must match the secret key in the Generator App
    private const val SECRET_KEY = "123456789"

    private const val PREFS_FILE    = "thunder_license_prefs"
    private const val KEY_USERNAME  = "lv_username"
    private const val KEY_TOKEN     = "lv_token"

    enum class Status {
        VALID,          // credentials OK and not expired
        EXPIRED,        // valid credentials but past expiry date
        INVALID,        // signature wrong / tampered
        NOT_ACTIVATED   // no credentials stored yet
    }

    data class LicenseInfo(
        val status: Status,
        val username: String = "",
        val expiryDate: String = "",   // "YYYY-MM-DD"
        val daysRemaining: Long = 0
    )

    /** Activate with a username + license key. Returns true if genuine and not expired. */
    fun activate(context: Context, username: String, licenseKey: String): Boolean {
        val payload = decodeAndVerify(username, licenseKey) ?: return false
        val prefs = getPrefs(context)
        prefs.edit()
            .putString(KEY_USERNAME, username)
            .putString(KEY_TOKEN, licenseKey)
            .apply()
        return !isExpired(payload.getString("exp"))
    }

    /** Call on every app launch to check stored credentials. */
    fun check(context: Context): LicenseInfo {
        val prefs  = getPrefs(context)
        val user   = prefs.getString(KEY_USERNAME, null) ?: return LicenseInfo(Status.NOT_ACTIVATED)
        val token  = prefs.getString(KEY_TOKEN,    null) ?: return LicenseInfo(Status.NOT_ACTIVATED)

        val payload = decodeAndVerify(user, token)
            ?: return LicenseInfo(Status.INVALID, username = user)

        val expiry = payload.getString("exp")
        val days   = daysUntil(expiry)

        return if (days < 0) {
            LicenseInfo(Status.EXPIRED,  username = user, expiryDate = expiry, daysRemaining = 0)
        } else {
            LicenseInfo(Status.VALID,    username = user, expiryDate = expiry, daysRemaining = days)
        }
    }

    /** Returns stored username, or empty string if not activated. */
    fun getUsername(context: Context): String =
        getPrefs(context).getString(KEY_USERNAME, "") ?: ""

    /** Clear stored credentials (e.g. user wants to enter a new key). */
    fun clear(context: Context) { getPrefs(context).edit().clear().apply() }

    // ── Internal helpers ───────────────────────────────────────────────────

    private fun decodeAndVerify(username: String, licenseKey: String): JSONObject? = try {
        val parts = licenseKey.trim().split(".")
        if (parts.size != 2) null
        else {
            val payloadBytes = Base64.decode(parts[0], Base64.URL_SAFE or Base64.NO_WRAP)
            val sigBytes     = Base64.decode(parts[1], Base64.URL_SAFE or Base64.NO_WRAP)
            val message      = "$username:${parts[0]}"
            val expected     = hmacSha256(SECRET_KEY, message)
            if (!expected.contentEquals(sigBytes)) null
            else {
                val payload = JSONObject(String(payloadBytes, Charsets.UTF_8))
                if (payload.optString("usr") != username) null else payload
            }
        }
    } catch (e: Exception) { null }

    private fun hmacSha256(key: String, data: String): ByteArray {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(key.toByteArray(Charsets.UTF_8), "HmacSHA256"))
        return mac.doFinal(data.toByteArray(Charsets.UTF_8))
    }

    private fun isExpired(expiryDate: String): Boolean = daysUntil(expiryDate) < 0

    private fun daysUntil(expiryDate: String): Long = try {
        val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
        sdf.timeZone = java.util.TimeZone.getTimeZone("UTC")
        val exp = sdf.parse(expiryDate)?.time ?: return -1L
        (exp - System.currentTimeMillis()) / (1000L * 60 * 60 * 24)
    } catch (e: Exception) { -1L }

    private fun getPrefs(context: Context): android.content.SharedPreferences {
        val masterKey = MasterKey.Builder(context)
            .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
            .build()
        return EncryptedSharedPreferences.create(
            context,
            PREFS_FILE,
            masterKey,
            EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
            EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
        )
    }
}
